const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const rawUrl = (typeof body.url === 'string') ? body.url.trim() : '';
const explicit = (typeof body.platform === 'string') ? body.platform.trim().toLowerCase() : '';
const language = (typeof body.language === 'string') ? body.language.trim() : '';
if (!rawUrl) return [{ json: { ok: false, error: 'url is required' } }];
if (!/^https?:\/\/[^\s]+$/i.test(rawUrl)) return [{ json: { ok: false, error: 'invalid url', url: rawUrl } }];
const host = rawUrl.replace(/^https?:\/\//i, '').split(/[/?#]/)[0].toLowerCase();
let platform = '';
if (/(^|\.)tiktok\.com$/.test(host)) platform = 'tiktok';
else if (/(^|\.)youtube\.com$/.test(host) || /(^|\.)youtu\.be$/.test(host)) platform = 'youtube';
else if (/(^|\.)instagram\.com$/.test(host)) platform = 'instagram';
if (['tiktok', 'youtube', 'instagram'].includes(explicit)) platform = explicit;
let apiUrl = '';
if (platform === 'tiktok') {
  apiUrl = 'https://api.scrapecreators.com/v1/tiktok/video/transcript?url=' + encodeURIComponent(rawUrl) + (language ? '&language=' + encodeURIComponent(language) : '');
} else if (platform === 'youtube') {
  apiUrl = 'https://api.scrapecreators.com/v1/youtube/video/transcript?url=' + encodeURIComponent(rawUrl) + (language ? '&language=' + encodeURIComponent(language) : '');
}
return [{ json: { ok: true, url: rawUrl, platform, has_url: true, language, api_url: apiUrl } }];

const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const url = $('Detect transcript').first().json.url;
const status = Number(body.statusCode) || 0;
if (status === 402 || /out of credits/i.test(String(body.message || '') + String(body.error || ''))) {
  return [{ json: { ok: false, error: 'low_credits', status: status || null, url, credits_remaining: body.credits_remaining } }];
}
if (body.success === false) {
  return [{ json: { ok: false, error: 'api_error', status: status || null, message: body.message || '', url, credits_remaining: body.credits_remaining } }];
}
const raw = typeof body.transcript === 'string' ? body.transcript : '';
if (!raw) {
  return [{ json: { ok: false, error: 'transcript_not_found', url, detail: body.message || '' } }];
}
const lines = raw.split(/\r?\n/);
const segments = [];
let cur = null;
for (const ln of lines) {
  const m = ln.match(/(?:(\d{1,2}):)?(\d{2}):(\d{2})\.(\d{3})\s*-->\s*(?:(\d{1,2}):)?(\d{2}):(\d{2})\.(\d{3})/);
  if (m) {
    if (cur) segments.push(cur);
    const st = (+m[1] || 0) * 3600 + +m[2] * 60 + +m[3] + +m[4] / 1000;
    const en = (+m[5] || 0) * 3600 + +m[6] * 60 + +m[7] + +m[8] / 1000;
    cur = { start: Math.round(st * 1000) / 1000, end: Math.round(en * 1000) / 1000, text: '' };
  } else if (cur && ln.trim() && !/^WEBVTT/i.test(ln.trim())) {
    cur.text = (cur.text ? cur.text + ' ' : '') + ln.trim();
  }
}
if (cur) segments.push(cur);
const text = segments.map(s => s.text).join(' ').trim();
return [{ json: { ok: true, platform: 'tiktok', url, transcript: text || raw, segments, credits_charged: body.credits_charged, credits_remaining: body.credits_remaining } }];

