const PLATFORM = 'tiktok';
const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const d = $('Detect comments').first().json;
const url = d.url;
const limit = d.limit;
const status = Number(body.statusCode) || 0;
if (status === 402 || /out of credits/i.test(String(body.message || '') + String(body.error || ''))) {
  return [{ json: { ok: false, error: 'low_credits', status: status || null, url, credits_remaining: body.credits_remaining } }];
}
if (body.success === false) {
  return [{ json: { ok: false, error: 'api_error', status: status || null, message: body.message || '', url, credits_remaining: body.credits_remaining } }];
}
const raw = Array.isArray(body.comments) ? body.comments : [];
const comments = [];
for (const c of raw) {
  if (!c || typeof c !== 'object') continue;
  const user = c.user || {};
  const eng = c.engagement || {};
  const id = c.cid || c.id;
  if (id === null || id === undefined) continue;
  const username = user.unique_id || user.nickname || user.username || (c.author && c.author.name) || null;
  const text = c.text || c.content || '';
  let likes = 0;
  if (typeof c.digg_count === 'number') likes = c.digg_count;
  else if (typeof eng.likes === 'number') likes = eng.likes;
  else if (typeof c.comment_like_count === 'number') likes = c.comment_like_count;
  let replies = 0;
  if (typeof c.reply_comment_total === 'number') replies = c.reply_comment_total;
  else if (typeof eng.replies === 'number') replies = eng.replies;
  else if (typeof c.child_comment_count === 'number') replies = c.child_comment_count;
  let created_at = c.publishedTime || c.created_at || null;
  if (!created_at && typeof c.create_time === 'number') created_at = new Date(c.create_time * 1000).toISOString();
  comments.push({ id: String(id), username, text, likes, replies_count: replies, created_at });
}
comments.sort((a, b) => (b.likes || 0) - (a.likes || 0));
const top = comments.slice(0, limit);
const total = typeof body.total === 'number' ? body.total : comments.length;
return [{ json: { ok: true, platform: PLATFORM, url, count: top.length, total_available: total, comments: top, credits_charged: body.credits_charged, credits_remaining: body.credits_remaining } }];

