// GET /v1/account/credit-balance -> {creditCount: N} (бесплатный, 0 кредитов).
// Универсальный парсер: body(объект) -> raw -> JSON.parse(data); creditCount в разных местах.
// balance_unavailable (401/502/сеть/не-JSON) -> гейт ПРОПУСКАЕТ платную ветку (не блокирует цепочку).
const raw = ($json && typeof $json === 'object' && !Array.isArray($json)) ? $json : {};
const src = (() => { try { return $('Detect transcript').first().json; } catch (e) { return {}; } })();
const pass = (src && typeof src === 'object' && !Array.isArray(src)) ? src : {};
const body = (raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body)) ? raw.body : null;
let balance = null;
try {
  if (body && body.creditCount != null) {
    balance = Number(body.creditCount);
  } else if (raw.creditCount != null) {
    balance = Number(raw.creditCount);
  } else if (typeof raw.data === 'string') {
    balance = Number(JSON.parse(raw.data).creditCount);
  }
} catch (err) {
  balance = null;
}
if (balance == null || !Number.isFinite(balance)) {
  return [{ json: Object.assign({}, pass, { balance: -1, creditCount: -1, balance_unavailable: true }) }];
}
return [{ json: Object.assign({}, pass, { balance: balance, creditCount: balance, balance_unavailable: false }) }];

